@layer components {
  /* Bubble */

  [data-slot="bubble-group"] {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-width: 0;
  }

  [data-slot="bubble"] {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    max-width: 80%;
    min-width: 0;
    position: relative;
    width: fit-content;
  }

  :is([data-slot="bubble"][data-align="end"], [data-slot="message"][data-align="end"] [data-slot="bubble"]) {
    align-self: flex-end;
  }

  [data-slot="bubble"][data-variant="ghost"] {
    max-width: 100%;
  }

  [data-slot="bubble-content"] {
    border: 1px solid transparent;
    border-radius: calc(var(--vh-radius) * 1.5);
    font-size: 0.875rem;
    line-height: 1.625;
    max-width: 100%;
    min-width: 0;
    overflow: hidden;
    overflow-wrap: break-word;
    padding: 0.5rem 0.75rem;
    width: fit-content;
  }

  [data-slot="bubble"][data-align="end"] > [data-slot="bubble-content"] {
    align-self: flex-end;
  }

  :is(a, button)[data-slot="bubble-content"] {
    color: inherit;
    cursor: pointer;
    font: inherit;
    text-align: left;
    text-decoration: none;
    transition: background-color 150ms, color 150ms;
  }

  [data-slot="bubble"][data-variant="solid"] > [data-slot="bubble-content"] {
    background: var(--vh-primary);
    color: var(--vh-inverted);
  }

  /* Hover colors apply only where a pointer can hover, so a tap on a touch screen does not leave them on, as on the primitive rail. */
  @media (hover: hover) {
    [data-slot="bubble"][data-variant="solid"] > :is(a, button)[data-slot="bubble-content"]:hover {
      background: color-mix(in oklab, var(--vh-primary) 80%, transparent);
    }
  }

  [data-slot="bubble"][data-variant="soft"] > [data-slot="bubble-content"] {
    background: var(--vh-bg-muted);
  }

  @media (hover: hover) {
    [data-slot="bubble"][data-variant="soft"] > :is(a, button)[data-slot="bubble-content"]:hover {
      background: color-mix(in oklab, var(--vh-bg-elevated), var(--vh-highlighted) 5%);
    }
  }

  /* A soft bubble in a tone is a tint of that color on the page background. */
  [data-slot="bubble"][data-variant="soft"][data-tone="info"] {
    --vh-bubble-tone: var(--vh-info);
  }

  [data-slot="bubble"][data-variant="soft"][data-tone="success"] {
    --vh-bubble-tone: var(--vh-success);
  }

  [data-slot="bubble"][data-variant="soft"][data-tone="warning"] {
    --vh-bubble-tone: var(--vh-warning);
  }

  [data-slot="bubble"][data-variant="soft"][data-tone="error"] {
    --vh-bubble-tone: var(--vh-error);
  }

  [data-slot="bubble"][data-variant="soft"]:not([data-tone="neutral"]) > [data-slot="bubble-content"] {
    background: color-mix(in oklab, var(--vh-bubble-tone) 14%, var(--vh-bg));
  }

  @media (hover: hover) {
    [data-slot="bubble"][data-variant="soft"]:not([data-tone="neutral"]) > :is(a, button)[data-slot="bubble-content"]:hover {
      background: color-mix(in oklab, var(--vh-bubble-tone) 22%, var(--vh-bg));
    }
  }

  [data-slot="bubble"][data-variant="outline"] > [data-slot="bubble-content"] {
    background: var(--vh-bg);
    border-color: var(--vh-border);
  }

  [data-slot="bubble"][data-variant="ghost"] > [data-slot="bubble-content"] {
    background: transparent;
    border: none;
    border-radius: 0;
    padding: 0;
  }

  @media (hover: hover) {
    [data-slot="bubble"]:is([data-variant="outline"], [data-variant="ghost"]) > :is(a, button)[data-slot="bubble-content"]:hover {
      background: var(--vh-bg-elevated);
      color: var(--vh-highlighted);
    }
  }

  [data-slot="bubble"][data-variant="destructive"] > [data-slot="bubble-content"] {
    background: color-mix(in oklab, var(--vh-error) 12%, transparent);
    color: var(--vh-error);
  }

  @media (hover: hover) {
    [data-slot="bubble"][data-variant="destructive"] > :is(a, button)[data-slot="bubble-content"]:hover {
      background: color-mix(in oklab, var(--vh-error) 20%, transparent);
    }
  }

  [data-slot="bubble-reactions"] {
    align-items: center;
    background: var(--vh-bg-elevated);
    border-radius: 9999px;
    box-shadow: 0 0 0 3px var(--vh-bg);
    display: flex;
    flex-shrink: 0;
    font-size: 0.875rem;
    gap: 0.25rem;
    justify-content: center;
    padding: 0.125rem 0.375rem;
    position: absolute;
    width: fit-content;
    z-index: 10;
  }

  [data-slot="bubble-reactions"]:has(button) {
    padding: 0;
  }

  [data-slot="bubble-reactions"][data-side="top"] {
    top: 0;
    translate: 0 -75%;
  }

  [data-slot="bubble-reactions"][data-side="bottom"] {
    bottom: 0;
    translate: 0 75%;
  }

  [data-slot="bubble-reactions"][data-align="start"] {
    left: 0.75rem;
  }

  [data-slot="bubble-reactions"][data-align="end"] {
    right: 0.75rem;
  }
}

export { default as Bubble } from "./Bubble.vue";
export { default as BubbleContent } from "./BubbleContent.vue";
export { default as BubbleGroup } from "./BubbleGroup.vue";
export { default as BubbleReactions } from "./BubbleReactions.vue";
export type * from "./types.ts";

export type BubbleAlign = "start" | "end";
export type BubbleVariant = "solid" | "soft" | "outline" | "ghost" | "destructive";
export type BubbleTone = "neutral" | "success" | "warning" | "error" | "info";

export interface BubbleProps {
  /** The side the bubble sits on. Inside a `Message` with `align="end"`, it is `end` too. */
  align?: BubbleAlign;
  /** `solid` is the primary color, `soft` a light fill, `outline` a border, `ghost` no frame, and `destructive` an error. */
  variant?: BubbleVariant;
  /** The color of a `soft` bubble. `neutral` is the gray fill. */
  tone?: BubbleTone;
}

export interface BubbleSlots {
  /** `BubbleContent`, and `BubbleReactions` when the bubble has reactions. */
  default?: () => unknown;
}

export interface BubbleContentSlots {
  default?: () => unknown;
  /**
   * Renders the content as another element, such as a link or a button. Bind `props` to it, which holds the
   * `data-slot`, and render `children` inside it.
   */
  render?: (scope: { props: Record<string, unknown>; children: () => unknown }) => unknown;
}

export interface BubbleReactionsProps {
  /** The edge of the bubble that the reactions sit at. */
  align?: BubbleAlign;
  /** Above or below the bubble. */
  side?: "top" | "bottom";
}

export interface BubbleReactionsSlots {
  default?: () => unknown;
}
